"""RV2-A (routing v2 stage 1: batch-consistent assignment). Pre-registration: PREREG.md (generated by `prereg`, read-only afterwards).

    python research/growmoe_results/rv2a/run_rv2a.py tune   [--smoke] [--arm A_vote]    # training budget on dev seeds (A_new keeps M2-A's frozen budgets)
    python research/growmoe_results/rv2a/run_rv2a.py dev    [--smoke]                   # both arms on dev seeds -> dev_effects.json
    python research/growmoe_results/rv2a/run_rv2a.py prereg                             # bars + expected outcomes from dev_effects.json -> bars_rv2a.json, PREREG.md
    python research/growmoe_results/rv2a/run_rv2a.py run    [--smoke] [--arms A_new,A_vote] [--only OV-0.3] [--seeds 20-39]
    python research/growmoe_results/rv2a/run_rv2a.py report [--smoke]

Every number in the output is written by this script. ``--smoke`` shrinks everything and writes to ``_smoke/``; its outputs mean nothing.
Finished tasks are stored as files and skipped on a re-run. Run from the repository root.
"""

import argparse
import hashlib
import json
import math
import sys
import time
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
for _p in (HERE.parent / "m2a", HERE.parent / "m0", ROOT):
    sys.path.insert(0, str(_p))

import numpy as np                                                                      # noqa: E402
import torch                                                                            # noqa: E402

import run_m0 as M                                                                      # noqa: E402
import run_m2a as R2                                                                    # noqa: E402
from growmoe.config import PhyloCfg                                                     # noqa: E402
from growmoe.fairfight import BARS_RV2A, rv2a_decision, rv2a_verdicts, run_fast, run_record, tune_steps  # noqa: E402
from growmoe.metrics import paired_diff                                                 # noqa: E402
from growmoe.pools.phylo import PhyloMoE                                                # noqa: E402
from growmoe.streams import Segment, Stream                                             # noqa: E402
from growmoe.streams_m1 import function_regimes                                         # noqa: E402

M2A_TUNING = ROOT / "research" / "growmoe_results" / "m2a" / "tuning_m2a.json"
SMOKE_SEEDS = (20, 21)
STREAM_ORDER = ["F-30", "F-15", "S2-30", "OV-0.3", "OV-0.6", "OV-0.0", "OV-0.3-MIXED", "MIX-0.0", "MIX-0.3", "S1", "S4", "S7", "S2-5"]
LABEL = {"A_new": "A_new (M2-A default, per-sample assignment)", "A_vote": "A_vote (batch vote)", "A_voter": "A_voter (restricted batch vote)"}
_STREAMS: dict = {}


def family(name: str) -> str:
    return "func" if name.startswith(("OV-", "MIX-")) else R2.FAMILY[name]


# ------------------------------------------------------------------------------------------------ streams and arms
def mix_pairs(st: Stream) -> Stream:
    """Every two consecutive segments interleaved: each batch is a 50/50 mixture of two regimes (a guard stream, kept out of the package)."""
    segs, out, i = st.segments, [], 0
    while i < len(segs):
        if i + 1 < len(segs):
            a, b = segs[i], segs[i + 1]
            out.append(Segment(a.regime, a.first_visit and b.first_visit, torch.cat([a.x, b.x]), torch.cat([a.y, b.y]), torch.cat([a.src_ids, b.src_ids]),
                               torch.cat([a.y_clean, b.y_clean]), torch.cat([a.is_outlier, b.is_outlier]), None))
            i += 2
        else:
            out.append(segs[i])
            i += 1
    return Stream(st.name + "_mixed", st.d, st.n_classes, st.regimes, out, dict(st.meta))


def build_stream(name: str, seed: int, smoke: bool) -> Stream:
    if name.startswith(("OV-", "MIX-")):
        rho = float(name.split("-")[1])                                                 # "OV-0.3-MIXED" -> 0.3
        kw = dict(n_regimes=4, n_train=128, n_test=64) if smoke else dict(n_regimes=10)
        if name.startswith("MIX-"):
            return function_regimes(seed, overlap=rho, mixed_tail=1 if smoke else 4, **kw)
        st = function_regimes(seed, overlap=rho, **kw)
        return mix_pairs(st) if name.endswith("MIXED") else st
    return R2.build_stream(name, seed, smoke)


def get_stream(name: str, seed: int, smoke: bool) -> Stream:
    key = (name, seed, smoke)
    if key not in _STREAMS:
        if len(_STREAMS) >= 4:                                                          # bound the memory held by one worker
            _STREAMS.pop(next(iter(_STREAMS)))
        _STREAMS[key] = build_stream(name, seed, smoke)
    return _STREAMS[key]


def factory(method: str, st: Stream, seed: int, P: dict):
    """M0's frozen A settings with the repaired monitor; the arms differ only in the vote flag(s)."""
    kw = {**M.A_KW, "arm_monitor_after_infancy": True, "batch_vote": method != "A_new"}
    if method == "A_voter":
        kw["batch_vote_restricted"] = True
    return lambda: PhyloMoE(PhyloCfg(seed=seed, d=st.d, n_classes=st.n_classes, inner_steps=P["steps"], **kw))


def out_dir(args) -> Path:
    d = HERE / "_smoke" if args.smoke else HERE
    d.mkdir(parents=True, exist_ok=True)
    return d


def steps_for(method: str, name: str, tm_new: dict, tm_vote: dict) -> int:
    f = family(name)
    return tm_new["A_new"][f]["steps"] if method == "A_new" else tm_vote[method][f]["steps"]


# ------------------------------------------------------------------------------------------------ dev tuning
def tune_task(spec: dict) -> dict:
    fam, smoke, arm = spec["family"], spec["smoke"], spec["arm"]
    seeds = M.SMOKE_DEV if smoke else M.DEV_SEEDS
    assert all(s >= 100 for s in seeds), "tuning must use dev seeds only"
    name = M.TUNE_STREAM[fam]
    streams = {s: get_stream(name, s, smoke) for s in seeds}

    def score(steps: int) -> float:
        return float(np.mean([run_fast(factory(arm, streams[s], s, {"steps": steps}), streams[s], s, eval_every="final").acc for s in seeds]))

    t0 = time.perf_counter()
    res = tune_steps(score, grid=M.SMOKE_GRID if smoke else M.STEP_GRID, factor=M.STEP_FACTOR, cap=M.STEP_CAP)
    return {"family": fam, "arm": arm, "steps": res.best, "at_edge": res.at_edge, "table": {str(k): v for k, v in res.table.items()},
            "stream": name, "dev_seeds": list(seeds), "seconds": time.perf_counter() - t0, "peak_mb": M._peak_mb()}


def cmd_tune(args) -> None:
    out = out_dir(args)
    specs = [dict(family=f, smoke=args.smoke, arm=args.arm) for f in ("func", "perm", "types")]
    results = M._parallel(tune_task, specs, lambda s: out / "tune" / f"{s['arm']}__{s['family']}.json", args.workers, args.threads, "tune", args.force,
                          tag_of=lambda s: s["family"])
    path = out / "tuning_rv2a.json"
    tuning = json.loads(path.read_text(encoding="utf-8")) if path.exists() else {}
    tuning[args.arm] = {r["family"]: {"steps": r["steps"], "at_edge": r["at_edge"], "table": r["table"], "stream": r["stream"], "dev_seeds": r["dev_seeds"]}
                        for r in results}
    path.write_text(json.dumps(tuning, indent=1), encoding="utf-8")
    for f, v in tuning[args.arm].items():
        print(f"  {args.arm} {f:6s} steps={v['steps']:>3d}" + ("   ** at the edge of the search **" if v["at_edge"] else ""))


# ------------------------------------------------------------------------------------------------ runs (dev and confirmatory share the task)
def run_task(spec: dict) -> dict:
    name, seed, smoke = spec["stream"], spec["seed"], spec["smoke"]
    tm_new = json.loads(Path(spec["tuning_m2a"]).read_text(encoding="utf-8"))
    tm_vote = json.loads(Path(spec["tuning_rv2a"]).read_text(encoding="utf-8"))
    st = get_stream(name, seed, smoke)
    t0, recs = time.perf_counter(), []
    for m in spec["arms"]:
        P = {"steps": steps_for(m, name, tm_new, tm_vote)}
        res = run_fast(factory(m, st, seed, P), st, seed, eval_every="final")
        rec = run_record(name, m, seed, res, **P)
        minority = st.meta.get("minority_regimes") or []
        if name.startswith("MIX-") and minority:                                        # the statement reads the minority regimes only
            rec["acc_all"] = rec["acc"]
            rec["acc"] = float(np.mean([res.per_regime[r] for r in minority]))
        recs.append(rec)
    return {"spec": {k: spec[k] for k in ("stream", "seed", "smoke", "arms")}, "records": recs, "seconds": time.perf_counter() - t0, "peak_mb": M._peak_mb()}


def _specs(args, out: Path, seeds, arms, streams):
    order = {n: i for i, n in enumerate(STREAM_ORDER)}
    return sorted([dict(stream=n, seed=s, smoke=args.smoke, arms=arms, tuning_m2a=str(M2A_TUNING), tuning_rv2a=str(out / "tuning_rv2a.json"))
                   for n in streams for s in seeds], key=lambda s: (order[s["stream"]], s["seed"]))


def cmd_dev(args) -> None:
    out = out_dir(args)
    if not (out / "tuning_rv2a.json").exists():
        sys.exit("tuning_rv2a.json is missing: run the tune step first")
    seeds = M.SMOKE_DEV if args.smoke else M.DEV_SEEDS
    assert all(s >= 100 for s in seeds)
    specs = _specs(args, out, seeds, ["A_new", "A_vote"], STREAM_ORDER)
    tasks = M._parallel(run_task, specs, lambda s: out / "dev" / f"{s['stream']}__{s['seed']}.json", args.workers, args.threads, "dev", args.force,
                        tag_of=lambda s: f"{s['stream']} seed {s['seed']}")
    runs = [r for t in tasks for r in t["records"]]
    effects = {}
    for n in STREAM_ORDER:
        a = {r["seed"]: r["acc"] for r in runs if r["stream"] == n and r["method"] == "A_vote"}
        b = {r["seed"]: r["acc"] for r in runs if r["stream"] == n and r["method"] == "A_new"}
        effects[n] = 100.0 * float(np.mean([a[s] - b[s] for s in sorted(set(a) & set(b))]))
    (out / "dev_effects.json").write_text(json.dumps(effects, indent=1), encoding="utf-8")
    print("dev effect (A_vote - A_new, points, mean of dev seeds):")
    for n, e in effects.items():
        print(f"  {n:14s} {e:+6.1f}")


# ------------------------------------------------------------------------------------------------ pre-registration
def _floor_half(x: float) -> float:
    return math.floor(x * 2.0) / 2.0


def make_bars(effects: dict):
    """Bars stay at the spec's value unless the dev effect is below 1.5 x the bar; then the bar drops to effect / 1.5 (at least 0.5)."""
    members = {"V1": ["OV-0.3"], "V2": ["F-15", "F-30"], "V3": ["OV-0.6"]}
    bars, expected = {}, {}
    for sid, streams in members.items():
        eff = min(effects[s] for s in streams)
        bar = BARS_RV2A[sid]
        if eff < 1.5 * bar:
            bar = max(0.5, _floor_half(max(eff, 0.0) / 1.5))
        bars[sid] = bar
        expected[sid] = "PASS" if eff > bar else "FAIL"
    for gid, stream in {"G1": "S1", "G2": "S2-5", "G3": "S2-30", "G4": "S4", "G5": "OV-0.0", "G6": "OV-0.3-MIXED"}.items():
        expected[gid] = "FAIL" if effects[stream] < -3.0 else "PASS"
    expected["GM"] = "FAIL" if min(effects["MIX-0.0"], effects["MIX-0.3"]) < -3.0 else "PASS"
    expected["G7"] = "PASS"
    return bars, expected


def _sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()[:12] if path.exists() else "missing"


def cmd_prereg(args) -> None:
    out = out_dir(args)
    effects = json.loads((out / "dev_effects.json").read_text(encoding="utf-8"))
    bars, expected = make_bars(effects)
    tm_vote = json.loads((out / "tuning_rv2a.json").read_text(encoding="utf-8"))
    tm_new = json.loads(M2A_TUNING.read_text(encoding="utf-8"))
    bars_path = out / "bars_rv2a.json"
    bars_path.write_text(json.dumps({"bars": bars, "expected": expected, "dev_effects": effects, "written": time.strftime("%Y-%m-%d %H:%M:%S")}, indent=1),
                         encoding="utf-8")
    rules = {k: v["rule"] for k, v in rv2a_verdicts([], bars, expected).items()}
    L = ["# RV2-A pre-registration (generated by run_rv2a.py prereg; written before any confirmatory seed ran)\n",
         "Spec: `docs/superpowers/specs/2026-10-10-routing-v2-design.md` section 4. Arms: `A_new` = M0's frozen A settings with `arm_monitor_after_infancy=True` and "
         "`batch_vote=False`; `A_vote` = the same with `batch_vote=True` (`batch_vote_share=0.5`, `batch_vote_min=8`). Confirmatory seeds 20-39; dev seeds 100-102; batch 64.\n",
         "## Statements\n", "| ID | Rule | Expected | Dev effect (points) |", "|---|---|---|---|"]
    for k, rule in rules.items():
        dev = (f"{effects['OV-0.3']:+.1f}" if k == "V1" else f"{effects['F-15']:+.1f} / {effects['F-30']:+.1f}" if k == "V2" else f"{effects['OV-0.6']:+.1f}" if k == "V3" else "-")
        L.append(f"| {k} | {rule} | {expected[k]} | {dev} |")
    L += ["", "## Training budgets (steps per batch, chosen on dev seeds; frozen by hash)\n", "| Arm | func | perm | types |", "|---|---|---|---|",
          f"| A_new (M2-A) | {tm_new['A_new']['func']['steps']} | {tm_new['A_new']['perm']['steps']} | {tm_new['A_new']['types']['steps']} |",
          f"| A_vote | {tm_vote['A_vote']['func']['steps']} | {tm_vote['A_vote']['perm']['steps']} | {tm_vote['A_vote']['types']['steps']} |", "",
          "## Decision rule (verbatim from the spec)\n",
          "Adopt the plain vote iff V1 and every guard pass (V2 and V3 are recorded, not gating); else run the restricted vote (a sample moves only if the modal "
          "expert's own gate accepts it) as the fallback on the same seeds and adopt it iff it passes V1 and every guard; else neither. V1 failing means the "
          "contamination mechanism claim was wrong: stop, re-diagnose, stage 3 is not started on this premise.\n",
          "## Provenance\n",
          f"spec {_sha(ROOT / 'docs/superpowers/specs/2026-10-10-routing-v2-design.md')}; phylo.py {_sha(ROOT / 'growmoe/pools/phylo.py')}; config.py {_sha(ROOT / 'growmoe/config.py')}; "
          f"fairfight.py {_sha(ROOT / 'growmoe/fairfight.py')}; this script {_sha(Path(__file__))}; tuning_m2a.json {_sha(M2A_TUNING)}; "
          f"tuning_rv2a.json {_sha(out / 'tuning_rv2a.json')}; bars_rv2a.json {_sha(bars_path)}.\n"]
    (out / "PREREG.md").write_text("\n".join(L), encoding="utf-8")
    for p in (out / "tuning_rv2a.json", bars_path):
        print(f"{p.name} frozen, sha256 {M.freeze_check(p)[:16]}")
    print("bars", bars, "expected", expected)


# ------------------------------------------------------------------------------------------------ confirmatory run
def cmd_run(args) -> None:
    out = out_dir(args)
    tuning, bars_path = out / "tuning_rv2a.json", out / "bars_rv2a.json"
    if args.smoke:
        seeds = SMOKE_SEEDS
    else:
        for p in (tuning, bars_path):
            if not p.exists():
                sys.exit(f"{p.name} is missing: run tune, dev and prereg first (the confirmatory run must use frozen budgets and bars)")
            print(f"{p.name} frozen, sha256 {M.freeze_check(p)[:16]}", flush=True)
        seeds = M.parse_seeds(args.seeds)
        assert all(20 <= s <= 39 for s in seeds), "the stage-1 confirmatory seeds are 20-39"
    arms = args.arms.split(",")
    streams = args.only.split(",") if args.only else STREAM_ORDER
    M._parallel(run_task, _specs(args, out, seeds, arms, streams),
                lambda s: out / "runs" / f"{'+'.join(s['arms'])}__{s['stream']}__{s['seed']}.json", args.workers, args.threads, "run", args.force,
                tag_of=lambda s: f"{s['stream']} seed {s['seed']} [{'+'.join(s['arms'])}]")


# ------------------------------------------------------------------------------------------------ report
def _pts(d) -> str:
    if d is None:
        return "missing"
    lo = "-inf" if d["ci_lo"] is None else f"{d['ci_lo']:+.1f}"
    hi = "+inf" if d["ci_hi"] is None else f"{d['ci_hi']:+.1f}"
    return f"{d['mean_diff_points']:+.1f} pts [{lo}, {hi}] (n={d['n']})"


def _numbers(k: str, v: dict) -> str:
    d = v["detail"]
    if v["verdict"] == "NOT MEASURABLE" and (d is None or (isinstance(d, dict) and all(x is None for x in d.values()))):
        return "missing data"
    if k == "G7":
        return f"mean alarms per run {d['mean_alarms']:.2f} (n={d['n']})"
    if k in ("V2", "GM"):
        return "; ".join(f"{s}: {_pts(x)}" for s, x in d.items())
    return _pts(d)


def cmd_report(args) -> None:
    out = out_dir(args)
    tasks = [json.loads(p.read_text(encoding="utf-8")) for p in sorted((out / "runs").glob("*.json"))]
    runs = [r for t in tasks for r in t["records"]]
    bp = out / "bars_rv2a.json"
    doc = json.loads(bp.read_text(encoding="utf-8")) if bp.exists() else {"bars": {}, "expected": {}}
    plain = rv2a_verdicts(runs, doc["bars"], doc["expected"], candidate="A_vote")
    restricted = rv2a_verdicts(runs, doc["bars"], doc["expected"], candidate="A_voter") if any(r["method"] == "A_voter" for r in runs) else None
    decision = rv2a_decision(plain, restricted)
    (out / "rv2a_runs.json").write_text(json.dumps({"runs": runs, "bars": doc, "verdicts": plain, "restricted": restricted, "decision": decision}, indent=1), encoding="utf-8")
    by: dict = {}
    for r in runs:
        by.setdefault((r["stream"], r["method"]), []).append(r)
    seeds = sorted({r["seed"] for r in runs})
    L = ["# RV2-A results (generated by run_rv2a.py; do not edit by hand)\n"]
    if args.smoke:
        L.append("> **SMOKE RUN. Tiny streams and grids. These numbers mean nothing.**\n")
    L.append(f"* PREREG.md sha256 {_sha(out / 'PREREG.md')}; bars_rv2a.json {_sha(bp)}; tuning_rv2a.json {_sha(out / 'tuning_rv2a.json')}; this script {_sha(Path(__file__))}; "
             f"fairfight.py {_sha(ROOT / 'growmoe/fairfight.py')}; phylo.py {_sha(ROOT / 'growmoe/pools/phylo.py')}.")
    if seeds:
        L.append(f"* Seeds {seeds[0]}-{seeds[-1]} ({len(seeds)}); compute summed over tasks {sum(t['seconds'] for t in tasks) / 60:.0f} min; "
                 f"largest worker peak memory {max(t['peak_mb'] for t in tasks):.0f} MB.\n")
    for title, res in (("Verdicts: plain vote (A_vote - A_new)", plain), ("Verdicts: restricted vote (A_voter - A_new)", restricted)):
        if res is None:
            continue
        L += [f"## {title}\n", "| ID | Rule | Verdict | Expected | Numbers |", "|---|---|---|---|---|"]
        for k, v in res.items():
            mark = {True: "as expected", False: "**AGAINST expectation**", None: "-"}[v["as_expected"]]
            L.append(f"| {k} | {v['rule']} | **{v['verdict']}** | {v['expected']} ({mark}) | {_numbers(k, v)} |")
        L.append("")
    L += [f"**Decision.** {decision}\n", "## Results per stream (final accuracy %; mean [95% t interval] over seeds; MIX-* = minority regimes)\n"]
    for name in STREAM_ORDER:
        present = [m for m in LABEL if (name, m) in by]
        if not present:
            continue
        L += [f"### {name}\n", "| Arm | Accuracy % | Experts | Spawns / run | Extends / run | Alarms / run | n |", "|---|---|---|---|---|---|---|"]
        for m in present:
            rows = by[(name, m)]
            ev = {k: float(np.mean([r["event_counts"].get(k, 0) for r in rows])) for k in ("spawn", "extend", "alarm")}
            L.append(f"| {LABEL[m]} | {M._fmt_ci([r['acc'] for r in rows])} | {M._mean(rows, 'n_experts'):.1f} | {ev['spawn']:.1f} | {ev['extend']:.1f} | {ev['alarm']:.1f} | {len(rows)} |")
        for cand in ("A_vote", "A_voter"):
            ra, rb = {r["seed"]: r for r in by.get((name, cand), [])}, {r["seed"]: r for r in by.get((name, "A_new"), [])}
            common = sorted(set(ra) & set(rb))
            if len(common) >= 2:
                d = paired_diff([100 * ra[s]["acc"] for s in common], [100 * rb[s]["acc"] for s in common])
                L.append(f"\n{cand} - A_new: {d['mean_diff']:+.1f} pts [{d['ci_lo']:+.1f}, {d['ci_hi']:+.1f}], p(paired t) = {d['p_t']:.3g}, n = {d['n']}")
        L.append("")
    tp = out / "tuning_rv2a.json"
    if tp.exists():
        tm = json.loads(tp.read_text(encoding="utf-8"))
        L += ["## Training budgets (steps per batch; dev score by steps)\n", "| Arm | Family | Dev stream | Steps | At the edge? | Dev score by steps (%) |", "|---|---|---|---|---|---|"]
        for arm, fams in tm.items():
            for f, v in fams.items():
                L.append(f"| {arm} | {f} | {v['stream']} | {v['steps']} | {'yes' if v['at_edge'] else 'no'} | "
                         + ", ".join(f"{k}: {100 * s:.1f}" for k, s in sorted(v["table"].items(), key=lambda kv: int(kv[0]))) + " |")
    (out / "RESULTS_RV2A.md").write_text("\n".join(L) + "\n", encoding="utf-8")
    print(f"wrote {out / 'RESULTS_RV2A.md'}")
    for k, v in plain.items():
        print(f"  {k}: {v['verdict']:15s} (expected {v['expected']})")
    print(" ", decision)


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("cmd", choices=["tune", "dev", "prereg", "run", "report"])
    ap.add_argument("--smoke", action="store_true")
    ap.add_argument("--workers", type=int, default=2)
    ap.add_argument("--threads", type=int, default=3)
    ap.add_argument("--arm", default="A_vote")
    ap.add_argument("--arms", default="A_new,A_vote")
    ap.add_argument("--only", default="")
    ap.add_argument("--seeds", default="20-39")
    ap.add_argument("--force", action="store_true")
    args = ap.parse_args()
    torch.set_num_threads(args.threads)
    {"tune": cmd_tune, "dev": cmd_dev, "prereg": cmd_prereg, "run": cmd_run, "report": cmd_report}[args.cmd](args)


if __name__ == "__main__":
    main()
